mapper.insert:
INSERT INTO MOCK_KFTC_OAUTH_CODE (
    AUTH_CODE, CLIENT_ID, USER_SEQ_NO, SCOPE, REDIRECT_URI, USED_YN, EXPIRES_AT, CREATED_AT
) VALUES (
    #{authCode}, #{clientId}, #{userSeqNo}, #{scope}, #{redirectUri},
    #{usedYn}, #{expiresAt, jdbcType=TIMESTAMP}, #{createdAt, jdbcType=TIMESTAMP}
)

mapper.update:
UPDATE MOCK_KFTC_OAUTH_CODE
SET USED_YN = 'Y'
WHERE AUTH_CODE = #{authCode}
  AND USED_YN = 'N'
  AND EXPIRES_AT >= #{now, jdbcType=TIMESTAMP}

mapper.insert:
INSERT INTO MOCK_KFTC_OAUTH_TOKEN (
    TOKEN_HASH, CLIENT_ID, USER_SEQ_NO, SCOPE, REVOKED_YN, EXPIRES_AT, CREATED_AT
) VALUES (
    #{tokenHash}, #{clientId}, #{userSeqNo, jdbcType=VARCHAR}, #{scope},
    #{revokedYn}, #{expiresAt, jdbcType=TIMESTAMP}, #{createdAt, jdbcType=TIMESTAMP}
)

mapper.update:
UPDATE MOCK_KFTC_ACCOUNT
SET BALANCE = BALANCE - #{amount},
    UPDATED_AT = #{now, jdbcType=TIMESTAMP}
WHERE FINTECH_USE_NUM = #{fintechUseNum}
  AND STATUS = 'ACTIVE'
  AND BALANCE >= #{amount}

UPDATE MOCK_KFTC_ACCOUNT
SET BALANCE = BALANCE + #{amount},
    UPDATED_AT = #{now, jdbcType=TIMESTAMP}
WHERE FINTECH_USE_NUM = #{fintechUseNum}
  AND STATUS = 'ACTIVE'

mapper.select:
SELECT COUNT(*)
FROM MOCK_KFTC_TRANSACTION
WHERE BANK_TRAN_ID = #{bankTranId}

mapper.insert:
INSERT INTO MOCK_KFTC_TRANSACTION (
    BANK_TRAN_ID, FINTECH_USE_NUM, INOUT_TYPE, TRAN_AMT, AFTER_BALANCE_AMT,
    PRINT_CONTENT, COUNTERPARTY_NAME, COUNTERPARTY_FIN_NUM, BRANCH_NAME, TRAN_AT
) VALUES (
    #{bankTranId}, #{fintechUseNum}, #{inoutType}, #{tranAmt}, #{afterBalanceAmt},
    #{printContent}, #{counterpartyName}, #{counterpartyFinNum, jdbcType=VARCHAR},
    #{branchName}, #{tranAt, jdbcType=TIMESTAMP}
)

mapper.select:
SELECT TX_ID AS txId, BANK_TRAN_ID AS bankTranId, FINTECH_USE_NUM AS fintechUseNum, INOUT_TYPE AS inoutType, TRAN_AMT AS tranAmt, AFTER_BALANCE_AMT AS afterBalanceAmt, PRINT_CONTENT AS printContent, COUNTERPARTY_NAME AS counterpartyName, COUNTERPARTY_FIN_NUM AS counterpartyFinNum, BRANCH_NAME AS branchName, TRAN_AT AS tranAt FROM MOCK_KFTC_TRANSACTION WHERE FINTECH_USE_NUM = #{fintechUseNum}
AND INOUT_TYPE = #{inoutType}
AND TRAN_AT >= #{from, jdbcType=TIMESTAMP}
AND TRAN_AT <= #{to, jdbcType=TIMESTAMP}
ORDER BY TRAN_AT ASC, TX_ID ASC
ORDER BY TRAN_AT DESC, TX_ID DESC
FETCH FIRST #{limit} ROWS ONLY
